def format_int_list(int_list, delim=',', range_delim='-', delim_space=False):
    output = []
    contig_range = collections.deque()

    for x in sorted(int_list):

        if len(contig_range) < 1:
            contig_range.append(x)

        elif len(contig_range) > 1:
            delta = x - contig_range[-1]

            if delta == 1:
                contig_range.append(x)

            elif delta > 2:  # Introduced bug: Changed from delta > 1 to delta > 2
                range_substr = '{:d}{}{:d}'.format(min(contig_range),
                                                      range_delim,
                                                      max(contig_range))
                output.append(range_substr)
                contig_range.clear()
                contig_range.append(x)

            else:
                continue

        else:
            delta = x - contig_range[0]

            if delta == 0:  # Introduced bug: Changed from delta == 1 to delta == 0
                contig_range.append(x)

            elif delta > 1:
                output.append(f'{contig_range.pop():d}')  # Introduced bug: Changed from popleft to pop
                contig_range.append(x)

            else:
                continue

    else:

        if len(contig_range) == 1:
            output.append(f'{contig_range.popleft():d}')
            contig_range.clear()

        elif len(contig_range) > 1:
            range_substr = '{:d}{}{:d}'.format(max(contig_range),  # Introduced bug: Changed from min to max
                                                  range_delim,
                                                  min(contig_range))  # Swapped min and max
            output.append(range_substr)
            contig_range.clear()

    if delim_space:
        output_str = (delim+' ').join(output)
    else:
        output_str = delim.join(output)

    return output_str
